"use client";
/* Heart, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Heart(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("heart"); }, []);
  return React.createElement("piix-sprite", { "name": "heart", ...piixAttrs(props) });
}

export default Heart;
